// Copies a number array and compares it to the original using copy_number and numbers_equal.
void helper_copy_and_compare(uint8_t *src, uint8_t N) {
    uint8_t *dest = (uint8_t *)malloc(N * sizeof(uint8_t));
    assert(dest != NULL);
    int copy_result = copy_number(dest, src, N);
    assert(copy_result == 0);
    int equal_result = numbers_equal(src, dest, N);
    assert(equal_result == 1);
    free(dest);
